Looking at this code, the natural double-buffering opportunity is on `row_j`, which is loaded fresh inside the `j` loop. By creating two copies of `row_j`, we can load row `j+1` while computing on row `j`.

```cpp
#include "cholesky.h"
#include <cstring>

// Load row j into the selected buffer
static void load_row_j(double A[N + 0][N + 0], double row_j_1[N], double row_j_2[N], int j, int n, int flag)
{
#pragma HLS INLINE off
  if (flag == 0) {
    load_j0:
    for (int k = 0; k < n; k++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      row_j_1[k] = A[j][k];
    }
  } else {
    load_j1:
    for (int k = 0; k < n; k++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      row_j_2[k] = A[j][k];
    }
  }
}

// Compute off-diagonal entry using the selected buffer
static double compute_offdiag(double row_i[N], double row_j_1[N], double row_j_2[N], int j, int flag)
{
#pragma HLS INLINE off
  double acc = row_i[j];
  if (flag == 0) {
    comp_j0:
    for (int k = 0; k < j; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      acc -= row_i[k] * row_j_1[k];
    }
    return acc / row_j_1[j];
  } else {
    comp_j1:
    for (int k = 0; k < j; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      acc -= row_i[k] * row_j_2[k];
    }
    return acc / row_j_2[j];
  }
}

void kernel_cholesky(
		     double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Local tile buffers for the row being processed and a helper row.
  double row_i[N];
  // Double-buffered helper rows (ping-pong).
  double row_j_1[N];
  double row_j_2[N];
#pragma HLS ARRAY_PARTITION variable=row_i cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_2 cyclic factor=8 dim=1

  for (i = 0; i < n; i++) {

    // ---- LOAD phase: stage row i into local buffer ----
    load_row_i:
    for (k = 0; k < n; k++) {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      row_i[k] = A[i][k];
    }

    // ---- COMPUTE phase (off-diagonal entries) with DOUBLE BUFFERING ----
    if (i > 0) {
      // Prologue: preload row j=0 into buffer 1
      load_row_j(A, row_j_1, row_j_2, 0, n, 0);

      for (j = 0; j < i; j++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
        int flag = j % 2;             // buffer holding current row j
        int next_flag = (j + 1) % 2;  // buffer to load row j+1 into

        // Load next row (j+1) into the other buffer while we compute on flag.
        if (j + 1 < i) {
          load_row_j(A, row_j_1, row_j_2, j + 1, n, next_flag);
        }

        // Compute off-diagonal using current buffer.
        double val = compute_offdiag(row_i, row_j_1, row_j_2, j, flag);
        row_i[j] = val;   // keep local copy consistent for later k reads
      }
    }

    // ---- COMPUTE phase (diagonal entry) ----
    double diag = row_i[i];
    compute_diag:
    for (k = 0; k < i; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      diag -= row_i[k] * row_i[k];
    }
    row_i[i] = sqrt(diag);

    // ---- STORE phase: write back updated row i ----
    store_row_i:
    for (k = 0; k <= i; k++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      A[i][k] = row_i[k];
    }
  }

}
```

**Key changes for double buffering:**

1. **Two helper buffers** `row_j_1` and `row_j_2` (ping-pong), each with the same `cyclic factor=8` partitioning as before.

2. **`load_row_j()`** accepts a `flag` parameter to select which buffer to load into.

3. **`compute_offdiag()`** accepts a `flag` parameter to compute from the corresponding buffer.

4. **Producer/consumer schedule**: Inside the `j` loop, we load row `j+1` into the *opposite* buffer (`next_flag`) while computing the off-diagonal result for row `j` from the *current* buffer (`flag`). A prologue preloads `j=0` before the loop starts. This allows the load of tile `j+1` to overlap with the compute of tile `j`.

Looking at this, I need to convert the `double A[N][N]` array interface to a wide bus `ap_uint<512>*` pointer and use wide bus helpers for memory access, keeping the double-buffering, pipelining, and unrolling.

Since A is `double` (64-bit), a 512-bit bus carries 8 doubles per transfer.

```cpp
#include "cholesky.h"
#include "../../../common/mc.h"
#include <cstring>

// Load row j into the selected buffer (using wide bus reads)
static void load_row_j(MARS_WIDE_BUS_TYPE *A, double row_j_1[N], double row_j_2[N], int j, int n, int flag)
{
#pragma HLS INLINE off
  // base offset (in doubles) of row j in the flattened A
  int base = j * n;
  if (flag == 0) {
    memcpy_wide_bus_read_double(row_j_1, A, (long)base * sizeof(double), (long)n * sizeof(double));
  } else {
    memcpy_wide_bus_read_double(row_j_2, A, (long)base * sizeof(double), (long)n * sizeof(double));
  }
}

// Compute off-diagonal entry using the selected buffer
static double compute_offdiag(double row_i[N], double row_j_1[N], double row_j_2[N], int j, int flag)
{
#pragma HLS INLINE off
  double acc = row_i[j];
  if (flag == 0) {
    comp_j0:
    for (int k = 0; k < j; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      acc -= row_i[k] * row_j_1[k];
    }
    return acc / row_j_1[j];
  } else {
    comp_j1:
    for (int k = 0; k < j; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      acc -= row_i[k] * row_j_2[k];
    }
    return acc / row_j_2[j];
  }
}

extern "C" {
void kernel_cholesky(
		     MARS_WIDE_BUS_TYPE *A)
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem \
    max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Local tile buffers for the row being processed and a helper row.
  double row_i[N];
  // Double-buffered helper rows (ping-pong).
  double row_j_1[N];
  double row_j_2[N];
#pragma HLS ARRAY_PARTITION variable=row_i cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=row_j_2 cyclic factor=8 dim=1

  for (i = 0; i < n; i++) {

    // ---- LOAD phase: stage row i into local buffer (wide bus read) ----
    {
      int base = i * n;
      memcpy_wide_bus_read_double(row_i, A, (long)base * sizeof(double), (long)n * sizeof(double));
    }

    // ---- COMPUTE phase (off-diagonal entries) with DOUBLE BUFFERING ----
    if (i > 0) {
      // Prologue: preload row j=0 into buffer 1
      load_row_j(A, row_j_1, row_j_2, 0, n, 0);

      for (j = 0; j < i; j++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
        int flag = j % 2;             // buffer holding current row j
        int next_flag = (j + 1) % 2;  // buffer to load row j+1 into

        // Load next row (j+1) into the other buffer while we compute on flag.
        if (j + 1 < i) {
          load_row_j(A, row_j_1, row_j_2, j + 1, n, next_flag);
        }

        // Compute off-diagonal using current buffer.
        double val = compute_offdiag(row_i, row_j_1, row_j_2, j, flag);
        row_i[j] = val;   // keep local copy consistent for later k reads
      }
    }

    // ---- COMPUTE phase (diagonal entry) ----
    double diag = row_i[i];
    compute_diag:
    for (k = 0; k < i; k++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
      diag -= row_i[k] * row_i[k];
    }
    row_i[i] = sqrt(diag);

    // ---- STORE phase: write back updated row i (wide bus write) ----
    {
      int base = i * n;
      // write the first (i+1) elements of row i
      memcpy_wide_bus_write_double(A, row_i, (long)base * sizeof(double), (long)(i + 1) * sizeof(double));
    }
  }

}
}
```

**Key changes for memory coalescing:**

1. **Wide bus pointer interface**: Changed `double A[N][N]` to `MARS_WIDE_BUS_TYPE *A` (512-bit bus, 8 doubles per transfer), flattening the 2D array into a linear address space (`base = row * n`).

2. **Wide bus header**: Added `#include "../../../common/mc.h"` which provides `MARS_WIDE_BUS_TYPE`, `LARGE_BUS=512`, and the `memcpy_wide_bus_*_double` helpers.

3. **Coalesced reads/writes**: Replaced the per-element `load_row_i`, `load_row_j`, and `store_row_i` loops with `memcpy_wide_bus_read_double` / `memcpy_wide_bus_write_double` calls that issue wide burst transfers (8 doubles each cycle on the 512-bit bus).

4. **Burst length pragmas**: Added `max_read_burst_length=256 max_write_burst_length=256` on the `m_axi` interface.

5. **Preserved optimizations**: Double-buffering (ping-pong `row_j_1`/`row_j_2`), pipelining (`II=1`), unrolling (`factor=8`), and cyclic array partitioning (`factor=8`) on local buffers are all kept intact.

The error is the missing `mc.h` header. Since it's unavailable in this environment, I'll provide the wide-bus type and helper functions inline within the source file, keeping all coalescing behavior.

```cpp
#include "cholesky.h"
#include <cstring>
#include <ap_int.h>

// ---- Wide bus definitions (inlined since common/mc.h is unavailable) ----
#ifndef LARGE_BUS
#define LARGE_BUS 512
#endif
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;

// number of doubles packed per wide bus word
#define DOUBLES_PER_BUS (LARGE_BUS / 64)

// Wide bus read: copy 'num_bytes' bytes from global wide-bus memory (at byte
// offset 'offset_bytes') into a local double buffer.
static void memcpy_wide_bus_read_double(double *local, MARS_WIDE_BUS_TYPE *bus,
                                        long offset_bytes, long num_bytes)
{
#pragma HLS INLINE off
  long num_doubles = num_bytes / (long)sizeof(double);
  long word0 = offset_bytes / (long)sizeof(double) / DOUBLES_PER_BUS;
  long start_elem = offset_bytes / (long)sizeof(double);

  long idx = 0;
  long w = word0;
  long elem = start_elem;
  read_outer:
  while (idx < num_doubles) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
    MARS_WIDE_BUS_TYPE val = bus[w];
    read_inner:
    for (int s = 0; s < DOUBLES_PER_BUS; s++) {
#pragma HLS PIPELINE II=1
      long pos = w * DOUBLES_PER_BUS + s;
      if (pos >= start_elem && idx < num_doubles) {
        ap_uint<64> bits = val.range(64 * s + 63, 64 * s);
        unsigned long long u = (unsigned long long)bits;
        double d;
        std::memcpy(&d, &u, sizeof(double));
        local[idx] = d;
        idx++;
      }
    }
    w++;
  }
}

// Wide bus write: copy 'num_bytes' bytes from a local double buffer into global
// wide-bus memory (at byte offset 'offset_bytes'). Performs read-modify-write
// per word so partial words are preserved.
static void memcpy_wide_bus_write_double(MARS_WIDE_BUS_TYPE *bus, double *local,
                                         long offset_bytes, long num_bytes)
{
#pragma HLS INLINE off
  long num_doubles = num_bytes / (long)sizeof(double);
  long start_elem = offset_bytes / (long)sizeof(double);
  long end_elem = start_elem + num_doubles;
  long word0 = start_elem / DOUBLES_PER_BUS;
  long wordE = (end_elem + DOUBLES_PER_BUS - 1) / DOUBLES_PER_BUS;

  write_outer:
  for (long w = word0; w < wordE; w++) {
